const animals = [
  // ===== BIOME 500: SAVANNE =====
  [501, 'Gnuer', 'Gnoe', 'Gnou', 'Ñu',
   'Gnuerne vandrer i enorme flokke over Afrikas savanner og er essentielle for økosystemets balance. Deres massive migrationer er et af naturens største spektakler.',
   'Gnoes trekken in enorme kuddes over de Afrikaanse savannes en zijn essentieel voor het evenwicht van het ecosysteem. Hun massale migraties zijn een van de grootste spektakels van de natuur.',
   'Les gnous migrent en énormes troupeaux à travers les savanes africaines et sont essentiels à l\'équilibre de l\'écosystème. Leurs migrations massives sont l\'un des plus grands spectacles de la nature.',
   'Los ñus migran en enormes manadas por las sabanas africanas y son esenciales para el equilibrio del ecosistema. Sus masivas migraciones son uno de los mayores espectáculos de la naturaleza.'],
  [502, 'Zebra', 'Zebra', 'Zèbre', 'Cebra',
   'Zebraens sorte og hvide striber er unikke som et fingeraftryk og hjælper med at forvirre rovdyr. De lever i tætte familiegrupper og kommunikerer via lyde og kropssprog.',
   'De zwart-witte strepen van de zebra zijn uniek als een vingerafdruk en helpen roofdieren te verwarren. Ze leven in hechte familiegroepen en communiceren via geluiden en lichaamstaal.',
   'Les rayures noires et blanches du zèbre sont uniques comme une empreinte digitale et aident à dérouter les prédateurs. Ils vivent en groupes familiaux étroits et communiquent par des sons et le langage corporel.',
   'Las rayas blancas y negras de la cebra son únicas como una huella dactilar y ayudan a confundir a los depredadores. Viven en grupos familiares estrechos y se comunican mediante sonidos y lenguaje corporal.'],
  [503, 'Gepard', 'Jachtluipaard', 'Guépard', 'Guepardo',
   'Gepardens er det hurtigste landpattedyr på Jorden og kan nå hastigheder på op til 120 km/t. Dens slanke krop og lange ben er perfekt tilpasset til højthastighedsjagt på åbne sletter.',
   'De cheetah is het snelste landzoogdier op aarde en kan snelheden bereiken tot 120 km/u. Zijn slanke lichaam en lange benen zijn perfect aangepast voor het jagen op hoge snelheid op open vlaktes.',
   'Le guépard est le mammifère terrestre le plus rapide de la Terre et peut atteindre des vitesses allant jusqu\'à 120 km/h. Son corps élancé et ses longues pattes sont parfaitement adaptés à la chasse à grande vitesse dans les plaines ouvertes.',
   'El guepardo es el mamífero terrestre más rápido de la Tierra y puede alcanzar velocidades de hasta 120 km/h. Su cuerpo esbelto y sus largas patas están perfectamente adaptadas para la caza a alta velocidad en llanuras abiertas.'],
  [504, 'Hyæne', 'Gevlekte hyena', 'Hyène tachetée', 'Hiena manchada',
   'Hyænen er en af Afrikas mest misforståede dyr. De er faktisk dygtige jægere og lever i komplekse matrilineære samfund med strenge hierarkier.',
   'De hyena is een van Afrika\'s meest misverstane dieren. Ze zijn eigenlijk bekwame jagers en leven in complexe matrilineaire samenlevingen met strenge hiërarchieën.',
   'La hyène est l\'un des animaux les plus mal compris d\'Afrique. Ce sont en réalité des chasseurs habiles qui vivent dans des sociétés matrilinéaires complexes avec des hiérarchies strictes.',
   'La hiena es uno de los animales más incomprendidos de África. En realidad son cazadores hábiles que viven en complejas sociedades matrilineales con jerarquías estrictas.'],
  [505, 'Næsehorn', 'Neushoorn', 'Rhinocéros', 'Rinoceronte',
   'Næsehornets horn er lavet af keratin — det samme materiale som vores negle. Disse majestætiske dyr er desværre stærkt truet på grund af krybskytteri.',
   'De hoorn van de neushoorn is gemaakt van keratine — hetzelfde materiaal als onze nagels. Deze majestuøse dieren zijn helaas ernstig bedreigd door stroperij.',
   'La corne du rhinocéros est faite de kératine — le même matériau que nos ongles. Ces animaux majestueux sont malheureusement gravement menacés par le braconnage.',
   'El cuerno del rinoceronte está hecho de queratina, el mismo material que nuestras uñas. Estos majestuosos animales lamentablemente están gravemente amenazados por la caza furtiva.'],
  [506, 'Flodhest', 'Nijlpaard', 'Hippopotame', 'Hipopótamo',
   'På trods af sit massive udseende er flodhesten et af Afrikas farligste dyr. Den tilbringer det meste af dagen i vand for at holde sig kølig og beskyttet mod solen.',
   'Ondanks zijn massieve uiterlijk is het nijlpaard een van de gevaarlijkste dieren van Afrika. Het brengt het grootste deel van de dag in het water door om koel te blijven en beschermd te zijn tegen de zon.',
   'Malgré son apparence massive, l\'hippopotame est l\'un des animaux les plus dangereux d\'Afrique. Il passe la majeure partie de la journée dans l\'eau pour rester frais et protégé du soleil.',
   'A pesar de su apariencia masiva, el hipopótamo es uno de los animales más peligrosos de África. Pasa la mayor parte del día en el agua para mantenerse fresco y protegido del sol.'],
  [507, 'Giraffe', 'Giraffe', 'Girafe', 'Jirafa',
   'Giraffen er verdens højeste dyr og kan nå op til 6 meter. Dens lange hals giver den adgang til blade øverst i akacietræer, som andre dyr ikke kan nå.',
   'De giraf is het hoogste dier ter wereld en kan tot 6 meter hoog worden. Zijn lange nek geeft hem toegang tot bladeren bovenin acaciabomen, die andere dieren niet kunnen bereiken.',
   'La girafe est le plus grand animal du monde et peut atteindre jusqu\'à 6 mètres de hauteur. Son long cou lui donne accès aux feuilles au sommet des acacias, que les autres animaux ne peuvent pas atteindre.',
   'La jirafa es el animal más alto del mundo y puede alcanzar hasta 6 metros de altura. Su largo cuello le da acceso a las hojas en la cima de las acacias, a las que otros animales no pueden llegar.'],
  [508, 'Afrikaansk olifant', 'Afrikaanse olifant', 'Éléphant d\'Afrique', 'Elefante africano',
   'Den afrikanske elefant er det største landdyr på Jorden. Disse intelligente dyr lever i komplekse familiegrupper ledet af en erfaren hunelefant og kommunikerer via infralyd.',
   'De Afrikaanse olifant is het grootste landdier op aarde. Deze intelligente dieren leven in complexe familiegroepen geleid door een ervaren koeinolifant en communiceren via infrasound.',
   'L\'éléphant d\'Afrique est le plus grand animal terrestre de la Terre. Ces animaux intelligents vivent en groupes familiaux complexes dirigés par une femelle expérimentée et communiquent par infrasons.',
   'El elefante africano es el animal terrestre más grande de la Tierra. Estos animales inteligentes viven en complejos grupos familiares liderados por una hembra experimentada y se comunican mediante infrasonidos.'],
  [509, 'Løve', 'Leeuw', 'Lion', 'León',
   'Løven er det eneste sociale stort kattedyr og lever i grupper kaldet flokke. Hunner jager i fællesskab, mens hannerne forsvarer territoriet og beskytter ungerne.',
   'De leeuw is de enige sociale grote katachtige en leeft in groepen die troepen worden genoemd. Vrouwtjes jagen samen, terwijl de mannetjes het territorium verdedigen en de jongen beschermen.',
   'Le lion est le seul grand félin social et vit en groupes appelés troupes. Les femelles chassent ensemble, tandis que les mâles défendent le territoire et protègent les petits.',
   'El león es el único felino grande social y vive en grupos llamados manadas. Las hembras cazan juntas, mientras los machos defienden el territorio y protegen a las crías.'],
  [510, 'Leopard', 'Luipaard', 'Léopard', 'Leopardo',
   'Leoparden er en mester i camouflage og er kendt for sin evne til at bære bytte op i træer for at beskytte det mod andre rovdyr. De er yderst tilpasningsdygtige og kan leve i mange forskellige habitater.',
   'De luipaard is een meester in camouflage en staat bekend om zijn vermogen om prooi in bomen te dragen om het te beschermen tegen andere roofdieren. Ze zijn uiterst aanpasbaar en kunnen in veel verschillende habitats leven.',
   'Le léopard est un maître du camouflage et est connu pour sa capacité à porter des proies dans les arbres pour les protéger des autres prédateurs. Ils sont extrêmement adaptables et peuvent vivre dans de nombreux habitats différents.',
   'El leopardo es un maestro del camuflaje y es conocido por su capacidad de llevar presas a los árboles para protegerlas de otros depredadores. Son extremadamente adaptables y pueden vivir en muchos hábitats diferentes.'],
  [511, 'Kenguruugle', 'Aardhog', 'Orycterope', 'Cerdo hormiguero',
   'Det er et nataktivt dyr med en lang snude og klistret tunge, der bruges til at fange myrer og termitter. Dens kraftige klør graver hurtigt underjordiske huler.',
   'Het is een nachtactief dier met een lange snuit en plakkerige tong, gebruikt om mieren en termieten te vangen. Zijn krachtige klauwen graven snel ondergrondse holen.',
   'C\'est un animal nocturne avec un long museau et une langue collante utilisée pour attraper fourmis et termites. Ses puissantes griffes creusent rapidement des terriers souterrains.',
   'Es un animal nocturno con un largo hocico y una lengua pegajosa utilizada para atrapar hormigas y termitas. Sus poderosas garras excavan rápidamente madrigueras subterráneas.'],
  [512, 'Jordegern', 'Grondeekhoorn', 'Écureuil fouisseur', 'Ardilla terrestre',
   'Jordegernet er et lille, socialt gnaverdyr, der lever i kolonier under jorden. Det er meget vogtsomt og bruger forskellige alarmlyde til at advare sine artsfæller om rovdyr.',
   'Het grondeekhoorn is een kleine, sociale knaagdier die in kolonies onder de grond leeft. Het is zeer waakzaam en gebruikt verschillende alarmgeluiden om soortgenoten te waarschuwen voor roofdieren.',
   'L\'écureuil fouisseur est un petit rongeur social qui vit en colonies sous terre. Il est très vigilant et utilise différents cris d\'alarme pour avertir ses congénères des prédateurs.',
   'La ardilla terrestre es un pequeño roedor social que vive en colonias bajo tierra. Es muy vigilante y utiliza diferentes llamadas de alarma para advertir a sus congéneres sobre los depredadores.'],
  [513, 'Gepardgazelle', 'Thomsongazelle', 'Gazelle de Thomson', 'Gacela de Thomson',
   'Thomsons gazelle er en af de hurtigste dyr på savannen og er kendetegnet ved sit karakteristiske sorte sideband. Den er et vigtigt byttedyr for mange afrikanske rovdyr.',
   'De Thomson\'s gazelle is een van de snelste dieren op de savanne en wordt gekenmerkt door zijn kenmerkende zwarte zijband. Het is een belangrijk prooidier voor veel Afrikaanse roofdieren.',
   'La gazelle de Thomson est l\'un des animaux les plus rapides de la savane et est caractérisée par sa bande latérale noire distinctive. C\'est une proie importante pour de nombreux prédateurs africains.',
   'La gacela de Thomson es uno de los animales más rápidos de la sabana y se caracteriza por su distintiva banda lateral negra. Es una presa importante para muchos depredadores africanos.'],
  [514, 'Bøffel', 'Buffel', 'Buffle africain', 'Búfalo africano',
   'Den afrikanske bøffel er et af de farligste dyr i Afrika. Tyre er berygtet for at angribe jægere og har en fejltagende hukommelse for dem, der har skadet dem.',
   'De Afrikaanse buffel is een van de gevaarlijkste dieren in Afrika. Stieren staan erom bekend jagers aan te vallen en hebben een beruchte geheugen voor degenen die hen pijn hebben gedaan.',
   'Le buffle africain est l\'un des animaux les plus dangereux d\'Afrique. Les taureaux sont réputés pour attaquer les chasseurs et ont une mémoire infâme pour ceux qui les ont blessés.',
   'El búfalo africano es uno de los animales más peligrosos de África. Los toros son famosos por atacar a los cazadores y tienen una infame memoria para quienes les han hecho daño.'],
  [515, 'Stribet hyæne', 'Gestreepte hyena', 'Hyène rayée', 'Hiena rayada',
   'I modsætning til den plettet hyæne er den stribede hyæne mere tilbagetrukken og lever alene eller i små grupper. Den er primært en ådselæder og spiller en vigtig rolle i sit økosystem.',
   'In tegenstelling tot de gevlekte hyena is de gestreepte hyena teruggetrokkener en leeft alleen of in kleine groepen. Het is voornamelijk een aaseter en speelt een belangrijke rol in zijn ecosysteem.',
   'Contrairement à la hyène tachetée, la hyène rayée est plus réservée et vit seule ou en petits groupes. Elle est principalement charognarde et joue un rôle important dans son écosystème.',
   'A diferencia de la hiena manchada, la hiena rayada es más reservada y vive sola o en pequeños grupos. Es principalmente carroñera y juega un papel importante en su ecosistema.'],
  [516, 'Ørken-vortesvín', 'Wrattenzwijn', 'Phacochère', 'Facóquero',
   'Vortesvinet er et hårdfør dyr, der tilpasser sig godt til tørre savanner. Det graver underjordiske huler og lever i familiegrupper, og er kendetegnet ved sine karakteristiske vorter og store hugtænder.',
   'Het wrattenzwijn is een taai dier dat zich goed aanpast aan droge savannes. Het graaft ondergrondse holen en leeft in familiegroepen, gekenmerkt door zijn kenmerkende wratten en grote slagtanden.',
   'Le phacochère est un animal robuste qui s\'adapte bien aux savanes sèches. Il creuse des terriers souterrains et vit en groupes familiaux, caractérisé par ses verrues distinctives et ses grandes défenses.',
   'El facóquero es un animal resistente que se adapta bien a las sabanas secas. Excava madrigueras subterráneas y vive en grupos familiares, caracterizado por sus verrugas distintivas y grandes colmillos.'],
  [517, 'Gepard-ørn', 'Kroonarend', 'Aigle martial', 'Águila marcial',
   'Krunerørnen er en af Afrikas mægtigste rovfugle. Den jager fra store højder og slår ned på byttedyr med imponerende kraft. Dens syn er op til otte gange skarpere end et menneskes.',
   'De krooneend is een van de machtigste roofvogels van Afrika. Het jaagt vanuit grote hoogten en slaat neer op prooi met indrukwekkende kracht. Zijn gezichtsscherpte is tot acht keer scherper dan die van een mens.',
   'L\'aigle martial est l\'un des rapaces les plus puissants d\'Afrique. Il chasse depuis de grandes hauteurs et frappe les proies avec une force impressionnante. Sa vue est jusqu\'à huit fois plus perçante que celle d\'un humain.',
   'El águila marcial es uno de los rapaces más poderosos de África. Caza desde grandes alturas y golpea a las presas con impresionante fuerza. Su visión es hasta ocho veces más aguda que la de un humano.'],
  [518, 'Sekretærfugl', 'Secretarisvogel', 'Secrétaire', 'Ave secretaria',
   'Sekretærfuglen er en usædvanlig rovfugl, der foretrækker at jage til fods. Den er berømt for sine lange ben og sin evne til at stampe slanger ihjel med kraftige spark.',
   'De secretarisvogel is een ongewone roofvogel die de voorkeur geeft aan jagen te voet. Het is beroemd om zijn lange benen en zijn vermogen om slangen dood te trappen met krachtige trappen.',
   'Le secrétaire est un rapace inhabituel qui préfère chasser à pied. Il est célèbre pour ses longues pattes et sa capacité à piétiner les serpents avec des coups de pied puissants.',
   'El ave secretaria es un rapaz inusual que prefiere cazar a pie. Es famoso por sus largas patas y su capacidad de patear serpientes hasta matarlas con poderosas patadas.'],
  [519, 'Struds', 'Struisvogel', 'Autruche', 'Avestruz',
   'Strudsen er verdens største fugl og kan ikke flyve, men er til gengæld verdens hurtigste tvebenede dyr. Den kan løbe med op til 70 km/t og har de største øjne af alle landdyr.',
   'De struisvogel is de grootste vogel ter wereld en kan niet vliegen, maar is wel het snelste tweevoetige dier ter wereld. Het kan rennen met tot 70 km/u en heeft de grootste ogen van alle landdieren.',
   'L\'autruche est le plus grand oiseau du monde et ne peut pas voler, mais est en revanche l\'animal bipède le plus rapide du monde. Elle peut courir jusqu\'à 70 km/h et a les plus grands yeux de tous les animaux terrestres.',
   'El avestruz es el ave más grande del mundo y no puede volar, pero es el animal bípedo más rápido del mundo. Puede correr hasta 70 km/h y tiene los ojos más grandes de todos los animales terrestres.'],
  [520, 'Pelikaner', 'Pelikaan', 'Pélican', 'Pelícano',
   'Pelikanens kendetegnende pungstrube kan holde op til tre gange så meget som dens mave. Disse sociale fugle jager ofte i gruppe og samarbejder om at drive fisk ind i lavt vand.',
   'De kenmerkende keelzak van de pelikaan kan tot drie keer zo veel bevatten als zijn maag. Deze sociale vogels jagen vaak in groepen en werken samen om vissen naar ondiep water te drijven.',
   'La poche gulaire distinctive du pélican peut contenir jusqu\'à trois fois plus que son estomac. Ces oiseaux sociaux chassent souvent en groupe et coopèrent pour rabattre les poissons vers les eaux peu profondes.',
   'La bolsa gular distintiva del pelícano puede contener hasta tres veces más que su estómago. Estas aves sociales a menudo cazan en grupo y cooperan para arrear peces hacia aguas poco profundas.'],
  [521, 'Marabu-stork', 'Maraboe', 'Marabout', 'Marabú',
   'Marabustorken er en af Afrikas største fugle med et vingefang på op til 3,7 meter. Det er en ådselæder og en vigtig del af savanneøkosystemet, da den rydder op efter andre rovdyr.',
   'De maraboe is een van de grootste vogels van Afrika met een vleugelspanwijdte van maximaal 3,7 meter. Het is een aaseter en een belangrijk onderdeel van het savanne-ecosysteem, omdat het opruimt na andere roofdieren.',
   'Le marabout est l\'un des plus grands oiseaux d\'Afrique avec une envergure allant jusqu\'à 3,7 mètres. C\'est un charognard et une partie importante de l\'écosystème de la savane, car il nettoie après les autres prédateurs.',
   'El marabú es una de las aves más grandes de África con una envergadura de hasta 3,7 metros. Es carroñero y una parte importante del ecosistema de la sabana, ya que limpia lo que dejan otros depredadores.'],
  [522, 'Termit-myresluger', 'Aardvarks Pangolin', 'Pangolin', 'Pangolín',
   'Pangolinens skæl er lavet af keratin — det samme som menneskelige negle. Truet af krybskytteri bruger den sin lange, klistrede tunge til at spise tusindvis af insekter om dagen.',
   'De schubben van de pangolin zijn gemaakt van keratine — hetzelfde als menselijke nagels. Bedreigd door stroperij, gebruikt het zijn lange, kleverige tong om elke dag duizenden insecten te eten.',
   'Les écailles du pangolin sont faites de kératine — comme les ongles humains. Menacé par le braconnage, il utilise sa longue langue collante pour manger des milliers d\'insectes par jour.',
   'Las escamas del pangolín están hechas de queratina, igual que las uñas humanas. Amenazado por la caza furtiva, usa su larga lengua pegajosa para comer miles de insectos al día.'],
  [523, 'Dikdik', 'Dik-dik', 'Dik-dik', 'Dik-dik',
   'Dikdikken er en af verdens mindste antilopearter og er ikke meget større end en hare. Den er monogam og lever i permanente par, der forsvarer et fast territorium.',
   'De dik-dik is een van de kleinste antiloopensoorten ter wereld en is niet veel groter dan een haas. Het is monogaam en leeft in permanente paren die een vast territorium verdedigen.',
   'Le dik-dik est l\'une des plus petites espèces d\'antilopes au monde et n\'est guère plus grand qu\'un lièvre. Il est monogame et vit en couples permanents qui défendent un territoire fixe.',
   'El dik-dik es una de las especies de antílope más pequeñas del mundo y no es mucho más grande que una liebre. Es monógamo y vive en parejas permanentes que defienden un territorio fijo.'],
  [524, 'Impala', 'Impala', 'Impala', 'Impala',
   'Implaen er en af Afrikas mest almindelige og elegante antilopearter. Den er berømt for sine imponerende spring på op til 3 meter i højden og 10 meter i længden.',
   'De impala is een van de meest voorkomende en elegante antilopensoorten in Afrika. Het is beroemd om zijn indrukwekkende sprongen van maximaal 3 meter hoog en 10 meter lang.',
   'L\'impala est l\'une des espèces d\'antilopes les plus communes et élégantes d\'Afrique. Elle est célèbre pour ses sauts impressionnants allant jusqu\'à 3 mètres de hauteur et 10 mètres de longueur.',
   'El impala es una de las especies de antílope más comunes y elegantes de África. Es famoso por sus impresionantes saltos de hasta 3 metros de altura y 10 metros de longitud.'],
  [525, 'Kuduer', 'Koedoe', 'Koudou', 'Kudú',
   'Kuduen er en stor antilope, der er kendetegnet ved hannens imponerende, spiralformede horn, der kan blive over 1,8 meter lange. Den er sky og lever typisk i tæt buskads.',
   'De koedoe is een grote antilope, gekenmerkt door de indrukwekkende spiraalvormige hoorns van het mannetje, die meer dan 1,8 meter lang kunnen worden. Het is schuw en leeft gewoonlijk in dicht struikgewas.',
   'Le koudou est une grande antilope caractérisée par les impressionnantes cornes en spirale du mâle, qui peuvent dépasser 1,8 mètre de longueur. Il est timide et vit généralement dans un fourré dense.',
   'El kudú es un gran antílope caracterizado por los impresionantes cuernos en espiral del macho, que pueden medir más de 1,8 metros de largo. Es tímido y generalmente vive en maleza densa.'],
  [526, 'Springbok', 'Springbok', 'Springbok', 'Springbok',
   'Springbokken er Sydafrikas nationalemblem og er berømt for sin imponerende adfærd kaldet "pronking", hvor den hopper lodret op i luften for at demonstrere sin vitalitet for rovdyr.',
   'De springbok is het nationale embleem van Zuid-Afrika en staat bekend om zijn indrukwekkende gedrag genaamd "pronken", waarbij het verticaal in de lucht springt om zijn vitaliteit aan roofdieren te demonstreren.',
   'Le springbok est l\'emblème national de l\'Afrique du Sud et est célèbre pour son comportement impressionnant appelé "pronking", où il saute verticalement dans les airs pour démontrer sa vitalité aux prédateurs.',
   'El springbok es el emblema nacional de Sudáfrica y es famoso por su impresionante comportamiento llamado "pronking", donde salta verticalmente al aire para demostrar su vitalidad a los depredadores.'],
  [527, 'Oryx', 'Oryx', 'Oryx', 'Órix',
   'Oryxen er en robust antilope tilpasset til at overleve i tørre ørkener og savanner. Dens lange, rette horn var sandsynligvis inspirationen bag myten om enhjørningen.',
   'De oryx is een robuuste antilope die is aangepast om te overleven in droge woestijnen en savannes. Zijn lange, rechte hoorns waren waarschijnlijk de inspiratie voor de mythe van de eenhoorn.',
   'L\'oryx est une antilope robuste adaptée pour survivre dans les déserts secs et les savanes. Ses longues cornes droites étaient probablement l\'inspiration du mythe de la licorne.',
   'El órix es un antílope robusto adaptado para sobrevivir en desiertos secos y sabanas. Sus largos cuernos rectos fueron probablemente la inspiración del mito del unicornio.'],
  [528, 'Serval', 'Serval', 'Serval', 'Serval',
   'Servalen er en mellemstor afrikansk kat med exceptionelt store ører, der giver den en overlegent hørelse til at lokalisere bytte. Den kan springe op til 3 meter i luften for at fange fugle.',
   'De serval is een middelgrote Afrikaanse kat met uitzonderlijk grote oren, die hem een superieur gehoor geven om prooi te lokaliseren. Het kan tot 3 meter in de luft springen om vogels te vangen.',
   'Le serval est un chat africain de taille moyenne avec des oreilles exceptionnellement grandes, lui conférant une ouïe supérieure pour localiser les proies. Il peut sauter jusqu\'à 3 mètres dans les airs pour attraper des oiseaux.',
   'El serval es un gato africano de tamaño mediano con orejas excepcionalmente grandes, que le proporcionan un oído superior para localizar presas. Puede saltar hasta 3 metros en el aire para atrapar aves.'],
  [529, 'Emu', 'Emoe', 'Émeu', 'Emú',
   'Emuen er verdens næststørste fugl og er hjemmehørende i Australien. Den kan ikke flyve men er en hurtig løber. Hannerne udruger æggene og tager sig primært af ungerne.',
   'De emoe is de op een na grootste vogel ter wereld en is inheems in Australië. Het kan niet vliegen maar is een snelle loper. Mannetjes broeden de eieren en zorgen voornamelijk voor de jongen.',
   'L\'émeu est le deuxième plus grand oiseau du monde et est originaire d\'Australie. Il ne peut pas voler mais est un coureur rapide. Les mâles couvent les œufs et s\'occupent principalement des petits.',
   'El emú es el segundo ave más grande del mundo y es originario de Australia. No puede volar pero es un corredor rápido. Los machos incuban los huevos y se encargan principalmente de las crías.'],
  [530, 'Grevys sebra', 'Grévy\'s zebra', 'Zèbre de Grévy', 'Cebra de Grévy',
   'Grévy\'s zebra er den største zebraart og kan kendes på sine tætte, smalle striber og store, afrundede ører. Den er stærkt truet og lever primært i Kenya og Etiopien.',
   'De Grévy\'s zebra is de grootste zebrasoort en kan worden herkend aan zijn dichte, smalle strepen en grote, ronde oren. Het is ernstig bedreigd en leeft voornamelijk in Kenia en Ethiopië.',
   'Le zèbre de Grévy est la plus grande espèce de zèbre et peut être reconnu à ses rayures étroites et denses et ses grandes oreilles rondes. Il est gravement menacé et vit principalement au Kenya et en Éthiopie.',
   'La cebra de Grévy es la especie de cebra más grande y puede reconocerse por sus rayas estrechas y densas y sus grandes orejas redondeadas. Está gravemente amenazada y vive principalmente en Kenia y Etiopía.'],
  [531, 'Kamel', 'Kameel', 'Chameau', 'Camello',
   'Kamelens pukkel indeholder ikke vand, som mange tror, men fedt. Dette fedt kan omdannes til energi og vand, når mad og drikke er knappe. Kamelet kan drikke op til 200 liter vand på én gang.',
   'De bult van de kameel bevat geen water, zoals velen denken, maar vet. Dit vet kan worden omgezet in energie en water wanneer voedsel en drinken schaars zijn. De kameel kan in één keer tot 200 liter water drinken.',
   'La bosse du chameau ne contient pas d\'eau comme beaucoup le croient, mais de la graisse. Cette graisse peut être convertie en énergie et en eau lorsque la nourriture et les boissons sont rares. Le chameau peut boire jusqu\'à 200 litres d\'eau en une seule fois.',
   'La joroba del camello no contiene agua como muchos creen, sino grasa. Esta grasa puede convertirse en energía y agua cuando los alimentos y bebidas son escasos. El camello puede beber hasta 200 litros de agua de una vez.'],
  [532, 'Dromader', 'Dromedaris', 'Dromadaire', 'Dromedario',
   'Dromedaren, eller enkeltpuklede kamel, er et mesterligt tilpasset ørkendyr. Den er beregnet til transport og har tjent mennesker i tusinder af år som pakkehest i tørre regioner.',
   'De dromedaris, of éénbultige kameel, is een meesterlijk aangepast woestijndier. Het is bedoeld voor transport en heeft mensen duizenden jaren gediend als pakdier in droge regio\'s.',
   'Le dromadaire, ou chameau à une bosse, est un animal désertique magistralement adapté. Il est destiné au transport et a servi les humains depuis des milliers d\'années comme bête de somme dans les régions arides.',
   'El dromedario, o camello de una joroba, es un animal desértico magistralmente adaptado. Está destinado al transporte y ha servido a los humanos durante miles de años como animal de carga en regiones áridas.'],
  [533, 'Warthog', 'Warthog', 'Phacochère commun', 'Facóquero común',
   'Det almindelige vortesvin er et robust og opportunistisk dyr, der lever i savanner og åbne skove. Det er kendetegnet ved sine knoglede ansigtsvorter og sable-lignende hugtænder.',
   'Het gewone wrattenzwijn is een robuust en opportunistisch dier dat leeft in savannes en open bossen. Het wordt gekenmerkt door zijn benige gezichtswaratten en sabel-achtige slagtanden.',
   'Le phacochère commun est un animal robuste et opportuniste qui vit dans les savanes et les forêts ouvertes. Il est caractérisé par ses verrues faciales osseuses et ses défenses en forme de sabre.',
   'El facóquero común es un animal robusto y oportunista que vive en sabanas y bosques abiertos. Se caracteriza por sus verrugas faciales óseas y colmillos en forma de sable.'],
  [534, 'Vildhund', 'Afrikaanse wilde hond', 'Lycaon', 'Licaón',
   'Den afrikanske vildhund er et af Afrikas mest effektive rovdyr og har en jagtsuccesrate på op til 80%. Den lever i tætte, kooperative flokke med komplekse sociale strukturer.',
   'De Afrikaanse wilde hond is een van de meest effectieve roofdieren van Afrika met een jachtsuccespercentage van tot 80%. Het leeft in hechte, coöperatieve pakketten met complexe sociale structuren.',
   'Le lycaon est l\'un des prédateurs les plus efficaces d\'Afrique avec un taux de réussite de chasse allant jusqu\'à 80%. Il vit dans des meutes étroites et coopératives avec des structures sociales complexes.',
   'El licaón es uno de los depredadores más eficientes de África con una tasa de éxito de caza de hasta el 80%. Vive en manadas estrechas y cooperativas con complejas estructuras sociales.'],
  [535, 'Gepard-gazelle (Thomsons)', 'Eland', 'Éland', 'Eland',
   'Elanden er den største antilope i verden. På trods af sin størrelse er den overraskende agil og kan hoppe over hegn på mere end 1,5 meters højde med lethed.',
   'De eland is de grootste antilope ter wereld. Ondanks zijn omvang is het verrassend behendig en kan het moeiteloos over hekken van meer dan 1,5 meter hoogte springen.',
   'L\'éland est la plus grande antilope du monde. Malgré sa taille, il est étonnamment agile et peut sauter par-dessus des clôtures de plus de 1,5 mètre de hauteur avec facilité.',
   'El eland es el antílope más grande del mundo. A pesar de su tamaño, es sorprendentemente ágil y puede saltar sobre vallas de más de 1,5 metros de altura con facilidad.'],
  [536, 'Hanuman-abe', 'Baviaan', 'Babouin', 'Babuino',
   'Bavianen er en af Afrikas mest udbredte primater og er tilpasset til både åbne savanner og klipper. De lever i store sociale grupper med komplekse hierarkier.',
   'De baviaan is een van de meest wijdverbreide primaten van Afrika en is aangepast aan zowel open savannes als rotsen. Ze leven in grote sociale groepen met complexe hiërarchieën.',
   'Le babouin est l\'un des primates les plus répandus d\'Afrique et est adapté aussi bien aux savanes ouvertes qu\'aux rochers. Ils vivent en grands groupes sociaux avec des hiérarchies complexes.',
   'El babuino es uno de los primates más extendidos de África y está adaptado tanto a sabanas abiertas como a rocas. Viven en grandes grupos sociales con jerarquías complejas.'],
  [537, 'Jordulv', 'Aardwolf', 'Protèle', 'Lobo de tierra',
   'Jordsvin ligner en lille hyæne, men er faktisk en insektæder. Den lever primært af termitter og kan spise op til 300.000 termitter om natten. Den er et nattaktivt og fredeligt dyr.',
   'De aardwolf lijkt op een kleine hyena, maar is eigenlijk een insectivoor. Het leeft voornamelijk van termieten en kan per nacht tot 300.000 termieten eten. Het is een nachtactief en vredig dier.',
   'Le protèle ressemble à une petite hyène, mais est en fait un insectivore. Il vit principalement de termites et peut manger jusqu\'à 300 000 termites par nuit. C\'est un animal nocturne et pacifique.',
   'El lobo de tierra se parece a una hiena pequeña, pero en realidad es un insectívoro. Vive principalmente de termitas y puede comer hasta 300.000 termitas por noche. Es un animal nocturno y pacífico.'],

  // ===== BIOME 600: DSCHUNGEL =====
  [601, 'Orangutang', 'Orang-oetan', 'Orang-outan', 'Orangután',
   'Orangutangerne er de nærmeste slægtninge til mennesket blandt de store aber og lever næsten udelukkende i trætoppene. De er kendte for deres ekstraordinære intelligens og brug af redskaber.',
   'Orang-oetans zijn de nauwste verwanten van de mens onder de grote apen en leven bijna uitsluitend in de boomtoppen. Ze staan bekend om hun buitengewone intelligentie en het gebruik van gereedschappen.',
   'Les orangs-outans sont les parents les plus proches de l\'homme parmi les grands singes et vivent presque exclusivement dans les cimes des arbres. Ils sont connus pour leur intelligence extraordinaire et l\'utilisation d\'outils.',
   'Los orangutanes son los parientes más cercanos del ser humano entre los grandes simios y viven casi exclusivamente en las copas de los árboles. Son conocidos por su extraordinaria inteligencia y uso de herramientas.'],
  [602, 'Gorilla', 'Gorilla', 'Gorille', 'Gorila',
   'Gorillaen er den største levende primat og lever i tætte familiegrupper ledet af en dominerende sølvryg-han. På trods af sit skræmmende udseende er gorillaen grundlæggende et fredeligt, planteæder.',
   'De gorilla is de grootste levende primaat en leeft in hechte familiegroepen geleid door een dominante zilverrug-mannetje. Ondanks zijn angstaanjagende uiterlijk is de gorilla in wezen een vredig, planteters.',
   'Le gorille est le plus grand primate vivant et vit en groupes familiaux étroits dirigés par un mâle dominant à dos argenté. Malgré son apparence effrayante, le gorille est fondamentalement un herbivore pacifique.',
   'El gorila es el primate vivo más grande y vive en grupos familiares estrechos liderados por un macho dominante de espalda plateada. A pesar de su aspecto aterrador, el gorila es fundamentalmente un herbívoro pacífico.'],
  [603, 'Schimpanse', 'Chimpansee', 'Chimpanzé', 'Chimpancé',
   'Chimpanser deler omkring 98,7% af deres DNA med mennesker og er vores nærmeste levende slægtninge. De bruger redskaber, løser komplekse problemer og har rige sociale liv.',
   'Chimpansees delen ongeveer 98,7% van hun DNA met mensen en zijn onze nauwste levende verwanten. Ze gebruiken gereedschappen, lossen complexe problemen op en hebben rijke sociale levens.',
   'Les chimpanzés partagent environ 98,7% de leur ADN avec les humains et sont nos plus proches parents vivants. Ils utilisent des outils, résolvent des problèmes complexes et ont des vies sociales riches.',
   'Los chimpancés comparten aproximadamente el 98,7% de su ADN con los humanos y son nuestros parientes vivos más cercanos. Usan herramientas, resuelven problemas complejos y tienen ricas vidas sociales.'],
  [604, 'Bonobo', 'Bonobo', 'Bonobo', 'Bonobo',
   'Bonoboen er nært beslægtet med chimpansen, men har en anderledes social struktur domineret af hunner. De er kendte for at bruge social adfærd til at løse konflikter frem for aggression.',
   'De bonobo is nauw verwant aan de chimpansee, maar heeft een andere sociale structuur die wordt gedomineerd door vrouwtjes. Ze staan bekend om het gebruik van sociaal gedrag om conflicten op te lossen in plaats van agressie.',
   'Le bonobo est étroitement lié au chimpanzé, mais a une structure sociale différente dominée par les femelles. Ils sont connus pour utiliser le comportement social pour résoudre les conflits plutôt que l\'agression.',
   'El bonobo está estrechamente relacionado con el chimpancé, pero tiene una estructura social diferente dominada por las hembras. Son conocidos por usar el comportamiento social para resolver conflictos en lugar de la agresión.'],
  [605, 'Gibboner', 'Gibbon', 'Gibbon', 'Gibón',
   'Gibbonerne er de mest akrobatiske primater og bevæger sig gennem junglen ved brachiation — at svinge fra gren til gren med armene. De er også kendte for deres komplekse sangkommunikation.',
   'De gibbons zijn de meest acrobatische primaten en bewegen zich door de jungle via brachiatie — zwaaien van tak tot tak met de armen. Ze staan ook bekend om hun complexe zangcommunicatie.',
   'Les gibbons sont les primates les plus acrobatiques et se déplacent dans la jungle par brachiation — en se balançant de branche en branche avec les bras. Ils sont également connus pour leur communication vocale complexe.',
   'Los gibones son los primates más acrobáticos y se mueven por la jungla mediante braquiación: balanceándose de rama en rama con los brazos. También son conocidos por su compleja comunicación vocal.'],
  [606, 'Tapir', 'Tapir', 'Tapir', 'Tapir',
   'Tapiren er et gammeldags pattedyr, der er overlevende fra en fordums tid. Den har en kort, bevægelig snabel og er semi-akvatisk, glad for at bade og svømme i floder. Den er nært beslægtet med heste og næsehorn.',
   'De tapir is een oeroud zoogdier dat een overblijfsel is uit een vergane tijd. Het heeft een korte, beweegbare slurf en is semi-aquatisch, houdt van Baden en zwemmen in rivieren. Het is nauw verwant aan paarden en neushoorns.',
   'Le tapir est un mammifère ancien qui est un survivant d\'une ère révolue. Il a une courte trompe mobile et est semi-aquatique, appréciant de se baigner et nager dans les rivières. Il est étroitement lié aux chevaux et aux rhinocéros.',
   'El tapir es un antiguo mamífero que es un superviviente de una era pasada. Tiene una corta trompa móvil y es semi-acuático, le gusta bañarse y nadar en ríos. Está estrechamente relacionado con los caballos y los rinocerontes.'],
  [607, 'Jaguarer', 'Jaguar', 'Jaguar', 'Jaguar',
   'Jaguaren er det tredje største kattedyr i verden og er det største i Amerika. Den er en dygtig svømmer og jager gerne i vand. I modsætning til leoparden bider jaguaren sit bytte i kraniet.',
   'De jaguar is het derde grootste katachtige ter wereld en het grootste in Amerika. Het is een bekwame zwemmer en jaagt graag in het water. In tegenstelling tot de luipaard bijt de jaguar zijn prooi in de schedel.',
   'Le jaguar est le troisième plus grand félin du monde et le plus grand des Amériques. C\'est un nageur habile et il aime chasser dans l\'eau. Contrairement au léopard, le jaguar mord sa proie dans le crâne.',
   'El jaguar es el tercer felino más grande del mundo y el más grande de las Américas. Es un nadador hábil y le gusta cazar en el agua. A diferencia del leopardo, el jaguar muerde a su presa en el cráneo.'],
  [608, 'Puma', 'Poema', 'Puma', 'Puma',
   'Pumaen er det næststørste kattedyr i Amerika og er en mester til at tilpasse sig forskellige levesteder, fra tætte jungler til åbne prærier. Den kan springe op til 6 meter vandret.',
   'De poema is het op een na grootste katachtige in Amerika en is een meester in het aanpassen aan verschillende habitats, van dichte jungles tot open graslanden. Het kan tot 6 meter horizontaal springen.',
   'Le puma est le deuxième plus grand félin des Amériques et est un maître de l\'adaptation à différents habitats, des jungles denses aux prairies ouvertes. Il peut sauter jusqu\'à 6 mètres horizontalement.',
   'El puma es el segundo felino más grande de las Américas y es un maestro de la adaptación a diferentes hábitats, desde densas selvas hasta praderas abiertas. Puede saltar hasta 6 metros horizontalmente.'],
  [609, 'Anaconda', 'Anaconda', 'Anaconda', 'Anaconda',
   'Anacondaen er en af verdens største slanger og kan blive over 8 meter lang. Den er en kvælerslange og lever i og nær vand i Sydamerikas regnskove. Den føder levende unger.',
   'De anaconda is een van de grootste slangen ter wereld en kan meer dan 8 meter lang worden. Het is een wurgslang en leeft in en nabij water in de regenwouden van Zuid-Amerika. Het baart levende jongen.',
   'L\'anaconda est l\'un des plus grands serpents du monde et peut dépasser 8 mètres de longueur. C\'est un serpent constricteur qui vit dans et près de l\'eau dans les forêts tropicales d\'Amérique du Sud. Il donne naissance à des petits vivants.',
   'La anaconda es una de las serpientes más grandes del mundo y puede medir más de 8 metros de longitud. Es una serpiente constrictora que vive en y cerca del agua en los bosques tropicales de América del Sur. Da a luz crías vivas.'],
  [610, 'Kaiman', 'Kaaiman', 'Caïman', 'Caimán',
   'Kaimanerne er mindre krokodilleidler fra Mellem- og Sydamerika. De er nære slægtninge til alligatorer og er vigtige rovdyr i det tropiske ferskvandsmiljø. De fleste arter er truede.',
   'Kaaiman zijn kleinere krokodillidaen uit Midden- en Zuid-Amerika. Ze zijn nauw verwant aan alligatoren en zijn belangrijke roofdieren in het tropische zoetwatermilieu. De meeste soorten zijn bedreigd.',
   'Les caïmans sont de plus petits crocodiliens d\'Amérique centrale et du Sud. Ils sont étroitement liés aux alligators et sont d\'importants prédateurs dans l\'environnement d\'eau douce tropical. La plupart des espèces sont menacées.',
   'Los caimanes son cocodrilos más pequeños de América Central y del Sur. Están estrechamente relacionados con los aligatores y son importantes depredadores en el entorno de agua dulce tropical. La mayoría de las especies están amenazadas.'],
  [611, 'Flyvende frø', 'Vliegende kikker', 'Grenouille volante', 'Rana voladora',
   'Den flyvende frø bruger sin store, halvt sammenvoksede tæer som faldskærm til at glide fra træ til træ. Den er en mester i kamouflage og er hjemmehørende i regnskovene i Sydøstasien.',
   'De vliegende kikker gebruikt zijn grote, gedeeltelijk vergroeide tenen als parachute om van boom tot boom te glijden. Het is een meester in camouflage en is inheems in de regenwouden van Zuidoost-Azië.',
   'La grenouille volante utilise ses grands orteils partiellement palmés comme parachute pour planer d\'arbre en arbre. C\'est un maître du camouflage et elle est originaire des forêts tropicales d\'Asie du Sud-Est.',
   'La rana voladora usa sus grandes dedos parcialmente palmeados como paracaídas para planear de árbol en árbol. Es un maestro del camuflaje y es originaria de los bosques tropicales del sudeste asiático.'],
  [612, 'Kamælon', 'Kameleon', 'Caméléon', 'Camaleón',
   'Kamæleonen er en mester til at skifte farve, men ikke bare for at camouflere sig — farveændringerne bruges primært til kommunikation og temperaturregulering. Hvert øje kan rotere uafhængigt.',
   'Het kameleon is een meester in van kleur veranderen, maar niet alleen voor camouflage — de kleurveranderingen worden voornamelijk gebruikt voor communicatie en temperatuurregulatie. Elk oog kan onafhankelijk roteren.',
   'Le caméléon est un maître du changement de couleur, mais pas seulement pour se camoufler — les changements de couleur sont principalement utilisés pour la communication et la régulation de la température. Chaque œil peut pivoter indépendamment.',
   'El camaleón es un maestro del cambio de color, pero no solo para camuflarse: los cambios de color se usan principalmente para comunicación y regulación de temperatura. Cada ojo puede rotar independientemente.'],
  [613, 'Boa constrictor', 'Boa constrictor', 'Boa constricteur', 'Boa constrictor',
   'Boa constrictoren er en stor, ikke-giftig slange, der kvæler sit bytte. Den er nattaktiv og en dygtig svømmer. Unge er levende, og hunner kan få op til 60 unger i en fødsel.',
   'De boa constrictor is een grote, niet-giftige slang die zijn prooi verstikt. Het is nachtactief en een bekwame zwemmer. Jongen worden levend geboren, en vrouwtjes kunnen tot 60 jongen per geboorte krijgen.',
   'Le boa constricteur est un grand serpent non venimeux qui étrangle sa proie. Il est nocturne et un nageur habile. Les jeunes naissent vivants, et les femelles peuvent avoir jusqu\'à 60 petits par naissance.',
   'La boa constrictor es una gran serpiente no venenosa que estrangula a su presa. Es nocturna y nadadora hábil. Las crías nacen vivas, y las hembras pueden tener hasta 60 crías en un parto.'],
  [614, 'Leguan', 'Leguaan', 'Iguane', 'Iguana',
   'Den grønne leguan er en stor firben, der lever i trætoppene i tropiske regnskove. Den er en planteæder og bruger sin hale til at svømme og forsvare sig. De kan blive over 2 meter lange.',
   'De groene leguaan is een grote hagedis die leeft in de boomtoppen van tropische regenwouden. Het is een herbivoor en gebruikt zijn staart om te zwemmen en zich te verdedigen. Ze kunnen meer dan 2 meter lang worden.',
   'L\'iguane vert est un grand lézard qui vit dans les cimes des forêts tropicales humides. C\'est un herbivore qui utilise sa queue pour nager et se défendre. Ils peuvent dépasser 2 mètres de longueur.',
   'La iguana verde es un lagarto grande que vive en las copas de los bosques tropicales húmedos. Es herbívora y usa su cola para nadar y defenderse. Pueden medir más de 2 metros de longitud.'],
  [615, 'Neontetra', 'Neonfisch', 'Néon de Paracheirodon', 'Neón tetra',
   'Neontetraen er en lille, livlig tropisk fisk fra Sydamerikas regnskovfloder. Den metalliske blå-røde stribe giver den et karakteristisk glimt i akvariet. Den lever i store stimer.',
   'De neontetra is een kleine, levendige tropische vis uit de regenwoudrivieren van Zuid-Amerika. De metallische blauw-rode streep geeft hem een kenmerkende glinstering in het aquarium. Het leeft in grote scholen.',
   'Le néon de Paracheirodon est un petit poisson tropical vif des rivières de la forêt tropicale d\'Amérique du Sud. Sa bande bleu-rouge métallique lui donne un éclat caractéristique dans l\'aquarium. Il vit en grands bancs.',
   'El neón tetra es un pequeño y vivaz pez tropical de los ríos de la selva tropical de América del Sur. La franja metálica azul-roja le da un destello característico en el acuario. Vive en grandes bancos.'],
  [616, 'Papegøje', 'Papegaai', 'Perroquet', 'Papagayo',
   'Papegøjer er ekstremt intelligente fugle, der er kendte for deres evne til at efterligne menneskelig tale. Mange arter lever i store, støjende flokke og har stærke, livslange parforhold.',
   'Papegaaien zijn uiterst intelligente vogels die bekend staan om hun vermogen om menselijk spraak na te bootsen. Veel soorten leven in grote, luidruchtige vluchten en hebben sterke, levenslange paarbanden.',
   'Les perroquets sont des oiseaux extrêmement intelligents connus pour leur capacité à imiter la parole humaine. De nombreuses espèces vivent en grandes volées bruyantes et ont des liens de couple forts et durables toute leur vie.',
   'Los loros son aves extremadamente inteligentes conocidas por su capacidad de imitar el habla humana. Muchas especies viven en grandes bandadas ruidosas y tienen fuertes vínculos de pareja de por vida.'],
  [617, 'Tukan', 'Toekan', 'Toucan', 'Tucán',
   'Tukanens enorme, farverige næb kan udgøre op til en tredjedel af dens samlede kroplængde. Det tjener som en termoregulerende enhed og bruges til at nå frugt på svage grene.',
   'De enorme, kleurrijke snavel van de toekan kan tot een derde van zijn totale lichaamslengte bedragen. Het dient als thermoregulerend apparaat en wordt gebruikt om fruit op zwakke takken te bereiken.',
   'L\'énorme bec coloré du toucan peut représenter jusqu\'à un tiers de sa longueur corporelle totale. Il sert d\'unité thermorégulatrice et est utilisé pour atteindre les fruits sur les branches fragiles.',
   'El enorme pico colorido del tucán puede representar hasta un tercio de su longitud corporal total. Sirve como unidad termorregulatoria y se usa para alcanzar frutas en ramas débiles.'],
  [618, 'Ara-papegøje', 'Ara', 'Ara', 'Guacamayo',
   'Ara-papegøjerne er de største papegøjer i verden og er kendte for deres strålende farvepragtige fjer. De er ekstremt intelligente, lever i par og kan opnå en alder på over 60 år.',
   'De ara\'s zijn de grootste papegaaien ter wereld en staan bekend om hun schitterende kleurrijke veren. Ze zijn uiterst intelligent, leven in paren en kunnen een leeftijd bereiken van meer dan 60 jaar.',
   'Les aras sont les plus grands perroquets du monde et sont connus pour leurs plumes vivement colorées. Ils sont extrêmement intelligents, vivent en couples et peuvent atteindre un âge de plus de 60 ans.',
   'Los guacamayos son los loros más grandes del mundo y son conocidos por sus plumas de colores brillantes. Son extremadamente inteligentes, viven en parejas y pueden alcanzar una edad de más de 60 años.'],
  [619, 'Kolibri', 'Kolibrie', 'Colibri', 'Colibrí',
   'Kolibrien er den eneste fugl, der kan flyve baglæns. Dens hjerte slår over 1200 gange i minuttet under flyvning. Den slår vingerne op til 80 gange i sekundet og lever primært af blomsterens nektar.',
   'De kolibrie is de enige vogel die achteruit kan vliegen. Zijn hart klopt tijdens de vlucht meer dan 1200 keer per minuut. Het slaat zijn vleugels tot 80 keer per seconde en leeft voornamelijk van bloemennectar.',
   'Le colibri est le seul oiseau qui puisse voler à reculons. Son cœur bat plus de 1200 fois par minute en vol. Il bat des ailes jusqu\'à 80 fois par seconde et vit principalement du nectar des fleurs.',
   'El colibrí es el único pájaro que puede volar hacia atrás. Su corazón late más de 1200 veces por minuto durante el vuelo. Bate sus alas hasta 80 veces por segundo y vive principalmente del néctar de las flores.'],
  [620, 'Glasvinge-sommerfugl', 'Glazenvleugelvlinder', 'Papillon aux ailes de verre', 'Mariposa alas de cristal',
   'Glasvinge-sommerfuglen har gennemsigtige vinger, der næsten er usynlige. Denne form for camouflage er sjælden i fuglekongen og giver den beskyttelse i sin regnskovshjem. Den er hjemmehørende i Mellemamerika.',
   'De glazenvleugelvlinder heeft transparante vleugels die bijna onzichtbaar zijn. Deze vorm van camouflage is zeldzaam in het vogelkoninkrijk en geeft hem bescherming in zijn regenwoudthuis. Het is inheems in Midden-Amerika.',
   'Le papillon aux ailes de verre a des ailes transparentes qui sont presque invisibles. Cette forme de camouflage est rare dans le règne animal et lui procure une protection dans sa maison en forêt tropicale. Il est originaire d\'Amérique centrale.',
   'La mariposa alas de cristal tiene alas transparentes que son casi invisibles. Esta forma de camuflaje es rara en el reino animal y le proporciona protección en su hogar en el bosque tropical. Es originaria de América Central.'],
  [621, 'Mantarokke', 'Mantarog', 'Raie manta', 'Manta raya',
   'Mantarokken er den største rokke i verden og kan have et vingefang på op til 7 meter. Den er fuldstændig ufarlig for mennesker og lever udelukkende af plankton, som den filtrerer fra vandet.',
   'De mantarog is de grootste rog ter wereld en kan een vleugelspanwijdte hebben van maximaal 7 meter. Het is volledig onschadelijk voor mensen en leeft uitsluitend van plankton, dat het uit het water filtert.',
   'La raie manta est la plus grande raie du monde et peut avoir une envergure allant jusqu\'à 7 mètres. Elle est totalement inoffensive pour les humains et vit exclusivement de plancton qu\'elle filtre de l\'eau.',
   'La manta raya es la raya más grande del mundo y puede tener una envergadura de hasta 7 metros. Es completamente inofensiva para los humanos y vive exclusivamente de plancton que filtra del agua.'],
  [622, 'Kæmpesalamander', 'Reuzensalamander', 'Salamandre géante', 'Salamandra gigante',
   'Den kinesiske kæmpesalamander er det største nulevende padde og kan blive op til 1,8 meter lang. Den er en levende fossil, da dens form næsten ikke har ændret sig i 170 millioner år. Den er stærkt truet.',
   'De Chinese reuzensalamander is de grootste levende amfibie en kan tot 1,8 meter lang worden. Het is een levend fossiel, omdat zijn vorm al bijna 170 miljoen jaar vrijwel niet is veranderd. Het is ernstig bedreigd.',
   'La salamandre géante de Chine est le plus grand amphibien vivant et peut atteindre jusqu\'à 1,8 mètre de longueur. C\'est un fossile vivant car sa forme n\'a presque pas changé depuis 170 millions d\'années. Elle est gravement menacée.',
   'La salamandra gigante de China es el anfibio vivo más grande y puede alcanzar hasta 1,8 metros de longitud. Es un fósil viviente ya que su forma apenas ha cambiado en 170 millones de años. Está gravemente amenazada.'],
  [623, 'Varanus', 'Varaan', 'Varan', 'Varano',
   'Varanerne er en gruppe store øgler, der er hjemmehørende i Afrika, Asien og Australien. De er kendte for deres todelte tunger, der bruges til at "lugte" luften. Komodovaranen er den største firben i verden.',
   'Varanen zijn een groep grote hagedissen die inheems zijn in Afrika, Azië en Australië. Ze staan bekend om hun gevorkte tongen, die worden gebruikt om de lucht te "ruiken". De Komodovaraan is de grootste hagedis ter wereld.',
   'Les varans sont un groupe de grands lézards originaires d\'Afrique, d\'Asie et d\'Australie. Ils sont connus pour leurs langues bifides, utilisées pour "sentir" l\'air. Le varan de Komodo est le plus grand lézard du monde.',
   'Los varanidos son un grupo de grandes lagartos nativos de África, Asia y Australia. Son conocidos por sus lenguas bífidas, usadas para "oler" el aire. El dragón de Komodo es el lagarto más grande del mundo.'],
  [624, 'Flagermus', 'Vleermuis', 'Chauve-souris', 'Murciélago',
   'Flagermus er de eneste pattedyr, der kan flyve rigtigt. De bruger ekkolokation til at navigere og jage insekter om natten. Mange arter er vigtige bestøvere og frøspredere i tropiske skove.',
   'Vleermuizen zijn de enige zoogdieren die werkelijk kunnen vliegen. Ze gebruiken echolocatie om te navigeren en insecten \'s nachts te jagen. Veel soorten zijn belangrijke bestuivers en zaadverspreiders in tropische bossen.',
   'Les chauves-souris sont les seuls mammifères capables de voler vraiment. Elles utilisent l\'écholocation pour naviguer et chasser les insectes la nuit. De nombreuses espèces sont d\'importants pollinisateurs et disperseurs de graines dans les forêts tropicales.',
   'Los murciélagos son los únicos mamíferos capaces de volar de verdad. Usan ecolocalización para navegar y cazar insectos por la noche. Muchas especies son importantes polinizadores y dispersores de semillas en los bosques tropicales.'],
  [625, 'Isbjørn', 'IJsbeer', 'Ours polaire', 'Oso polar',
   'Isbjørnen er verdens største landrovdyr og er perfekt tilpasset til det arktiske miljø. Dens hvide pels er faktisk gennemsigtig og hul, og dens hud er sort for at absorbere varme.',
   'De ijsbeer is het grootste landroofdier ter wereld en is perfect aangepast aan het arctische milieu. Zijn witte vacht is eigenlijk transparant en hol, en zijn huid is zwart om warmte te absorberen.',
   'L\'ours polaire est le plus grand prédateur terrestre du monde et est parfaitement adapté à l\'environnement arctique. Sa fourrure blanche est en réalité transparente et creuse, et sa peau est noire pour absorber la chaleur.',
   'El oso polar es el mayor depredador terrestre del mundo y está perfectamente adaptado al entorno ártico. Su pelaje blanco es en realidad transparente y hueco, y su piel es negra para absorber el calor.'],
  [626, 'Slangepapegøje', 'Slangenadder', 'Vipère serpent', 'Víbora de serpiente',
   'Giftslangerne er en stor gruppe slanger med et stort udvalg af giftsystemer. Fra de neurotoksiske kobraer til de hæmotoksiske hugorme. De spiller en vigtig rolle i at kontrollere gnaver-bestande.',
   'Giftige slangen zijn een grote groep slangen met een grote verscheidenheid aan giftsystemen. Van de neurotoxische cobra\'s tot de hemotoxische adders. Ze spelen een belangrijke rol bij het beheersen van knaagdierpopulaties.',
   'Les serpents venimeux sont un grand groupe de serpents avec une grande variété de systèmes de venin. Des cobras neurotoxiques aux vipères hémotoxiques. Ils jouent un rôle important dans le contrôle des populations de rongeurs.',
   'Las serpientes venenosas son un gran grupo de serpientes con una gran variedad de sistemas de veneno. Desde las cobras neurotóxicas hasta las víboras hemotóxicas. Juegan un papel importante en el control de las poblaciones de roedores.'],
  [627, 'Pungrokke', 'Elektrische rog', 'Torpille', 'Torpedo eléctrico',
   'Pungrokken er i stand til at generere elektriske stød på op til 220 volt for at bedøve bytte og afskrække rovdyr. Denne elektriske sans er også et fint navigations- og kommunikationsværktøj.',
   'De elektrische rog is in staat elektrische schokken van maximaal 220 volt te genereren om prooi te verdoven en roofdieren af te schrikken. Dit elektrische gevoel is ook een fijn navigatie- en communicatiegereedschap.',
   'Le torpille est capable de générer des chocs électriques allant jusqu\'à 220 volts pour étourdir les proies et dissuader les prédateurs. Ce sens électrique est aussi un outil de navigation et de communication très précis.',
   'El torpedo eléctrico es capaz de generar descargas eléctricas de hasta 220 voltios para aturdir presas y ahuyentar depredadores. Este sentido eléctrico también es una fina herramienta de navegación y comunicación.'],
  [628, 'Kæmpeblæksprutte', 'Reuzeninktvis', 'Calmar géant', 'Calamar gigante',
   'Kæmpeblæksprutten er et af oceanets mest mystiske skabninger. Den kan blive op til 13 meter lang og har de største øjne i dyreriget. Den lever dybt i havet og er sjældent observeret levende.',
   'De reuzeninktvis is een van de meest mysterieuze schepselen van de oceaan. Het kan tot 13 meter lang worden en heeft de grootste ogen in het dierenrijk. Het leeft diep in de zee en wordt zelden levend geobserveerd.',
   'Le calmar géant est l\'une des créatures les plus mystérieuses de l\'océan. Il peut atteindre jusqu\'à 13 mètres de longueur et a les plus grands yeux du règne animal. Il vit dans les profondeurs de la mer et est rarement observé vivant.',
   'El calamar gigante es una de las criaturas más misteriosas del océano. Puede medir hasta 13 metros de longitud y tiene los ojos más grandes del reino animal. Vive en las profundidades del mar y raramente se observa con vida.'],
  [629, 'Lemur', 'Lemur', 'Lémurien', 'Lémur',
   'Lemurerne er primater, der udelukkende lever på Madagaskar. De er meget mangfoldige i form og adfærd, fra de lille mus-lemurer til den store indri. Mange arter er kritisk truede på grund af skovrydning.',
   'Lemuren zijn primaten die uitsluitend op Madagaskar leven. Ze zijn zeer divers in vorm en gedrag, van de kleine muislemuren tot de grote indri. Veel soorten zijn kritiek bedreigd vanwege ontbossing.',
   'Les lémuriens sont des primates qui vivent exclusivement à Madagascar. Ils sont très diversifiés en forme et en comportement, des petits microcèbes aux grands indris. De nombreuses espèces sont gravement menacées en raison de la déforestation.',
   'Los lémures son primates que viven exclusivamente en Madagascar. Son muy diversos en forma y comportamiento, desde los pequeños ratones lémur hasta el gran indri. Muchas especies están críticamente amenazadas por la deforestación.'],
  [630, 'Bærby', 'Vetkwab', 'Aye-aye', 'Aye-aye',
   'Aye-ayen er en usædvanlig primat fra Madagaskar med en lang, tynd mellemfinger, der bruges til at hakke insekter ud af træ. Den er nattaktiv og er set som et dårligt varsel i lokal folklore.',
   'De aye-aye is een ongewone primaat uit Madagaskar met een lange, dunne middelvinger die wordt gebruikt om insecten uit hout te hakken. Het is nachtactief en wordt in de lokale folklore gezien als een slecht voorteken.',
   'L\'aye-aye est un primate inhabituel de Madagascar avec un long doigt médius fin utilisé pour extraire les insectes du bois. Il est nocturne et est considéré comme un mauvais présage dans le folklore local.',
   'El aye-aye es un primate inusual de Madagascar con un largo dedo medio delgado usado para extraer insectos de la madera. Es nocturno y es visto como un mal augurio en el folclore local.'],
  [631, 'Mandrilbavian', 'Mandril', 'Mandrill', 'Mandril',
   'Mandrilen er den største aber i verden og er kendetegnet ved hannernes farverige ansigt og bagdel. Disse livlige farver er tegn på dominans og sundhed og er mere intense, når hannen er ophidset.',
   'De mandril is de grootste aap ter wereld en wordt gekenmerkt door het kleurrijke gezicht en de achterste van de mannetjes. Deze levendige kleuren zijn tekens van dominantie en gezondheid en zijn intenser wanneer het mannetje opgewonden is.',
   'Le mandrill est le plus grand singe du monde et est caractérisé par le visage et les fesses colorés des mâles. Ces couleurs vives sont des signes de dominance et de santé et sont plus intenses lorsque le mâle est excité.',
   'El mandril es el mono más grande del mundo y se caracteriza por la cara y las nalgas de colores de los machos. Estos colores vivos son signos de dominancia y salud y son más intensos cuando el macho está excitado.'],
  [632, 'Gepard-fisk', 'Arapaima', 'Arapaïma', 'Arapaima',
   'Arapaïmaen er en af verdens største ferskvandsfisk og kan blive op til 3 meter lang. Den er en luftåndende fisk og kan overleve i vand med lavt iltindhold. Den har fast plads i Sydamerikansk folklore.',
   'De arapaima is een van de grootste zoetwatervisssen ter wereld en kan tot 3 meter lang worden. Het is een luchtademende vis en kan overleven in water met een laag zuurstofgehalte. Het heeft een vaste plaats in de Zuid-Amerikaanse folklore.',
   'L\'arapaïma est l\'un des plus grands poissons d\'eau douce du monde et peut atteindre jusqu\'à 3 mètres de longueur. C\'est un poisson respirant de l\'air qui peut survivre dans les eaux à faible teneur en oxygène. Il a une place de choix dans le folklore sud-américain.',
   'El arapaima es uno de los peces de agua dulce más grandes del mundo y puede medir hasta 3 metros de longitud. Es un pez que respira aire y puede sobrevivir en aguas con bajo contenido de oxígeno. Tiene un lugar especial en el folclore sudamericano.'],
  [633, 'Vandpyton', 'Waterpython', 'Python aquatique', 'Pitón acuática',
   'Vandpytoner er store slanger, der er tilpasset til et semi-akvatisk liv. De er dygtige svømmere og kan forblive under vand i lang tid. De kvæler deres bytte og sluger det helt.',
   'Waterpythons zijn grote slangen die zijn aangepast aan een semi-aquatisch leven. Ze zijn bekwame zwemmers en kunnen lange tijd onder water blijven. Ze verstikken hun prooi en slikken het in zijn geheel.',
   'Les pythons aquatiques sont de grands serpents adaptés à une vie semi-aquatique. Ils sont d\'habiles nageurs et peuvent rester sous l\'eau pendant de longues périodes. Ils étranglent leurs proies et les avalent entières.',
   'Las pitones acuáticas son grandes serpientes adaptadas a una vida semi-acuática. Son nadadoras hábiles y pueden permanecer bajo el agua durante largos períodos. Estrangulan a sus presas y las tragan enteras.'],
  [634, 'Tropisk insekt', 'Tropisch insect', 'Insecte tropical', 'Insecto tropical',
   'Tropiske insekter udgør en utrolig mangfoldighed af liv i regnskoven. Fra gigantiske biller til iøjnefaldende sommerfugle er de en afgørende del af ekonomerne og essentielle for bestøvning og nedbrydning.',
   'Tropische insecten vormen een ongelooflijke diversiteit aan leven in het regenwoud. Van reusachtige kevers tot opvallende vlinders, ze zijn een cruciaal onderdeel van de economieën en essentieel voor bestuiving en afbraak.',
   'Les insectes tropicaux constituent une incroyable diversité de vie dans la forêt tropicale. Des coléoptères géants aux papillons frappants, ils sont une partie cruciale des écosystèmes et essentiels à la pollinisation et à la décomposition.',
   'Los insectos tropicales constituyen una increíble diversidad de vida en el bosque tropical. Desde enormes escarabajos hasta llamativas mariposas, son una parte crucial de los ecosistemas y esenciales para la polinización y descomposición.'],
  [635, 'Tarantula', 'Tarantula', 'Tarentule', 'Tarántula',
   'Tarantulaer er de største edderkopper i verden og er fundet i varme, tropiske og subtropiske regioner verden over. Trods deres skræmmende udseende er de fleste arter ufarlige for mennesker.',
   'Tarantula\'s zijn de grootste spinnen ter wereld en worden gevonden in warme, tropische en subtropische regio\'s over de hele wereld. Ondanks hun angstaanjagende uiterlijk zijn de meeste soorten onschadelijk voor mensen.',
   'Les tarentules sont les plus grandes araignées du monde et se trouvent dans les régions chaudes, tropicales et subtropicales du monde entier. Malgré leur aspect effrayant, la plupart des espèces sont inoffensives pour les humains.',
   'Las tarántulas son las arañas más grandes del mundo y se encuentran en regiones cálidas, tropicales y subtropicales de todo el mundo. A pesar de su aspecto aterrador, la mayoría de las especies son inofensivas para los humanos.'],
  [636, 'Kæmpe-regnorm', 'Reuzenregenwormen', 'Ver de terre géant', 'Gusano de tierra gigante',
   'Kæmpe-regnorm fra tropiske regioner kan blive op til 3 meter lange. De er afgørende for jordens sundhed, da de blander og lufter jord, og deres udskillelser er rig på næringsstoffer.',
   'Reuzenwromens uit tropische regio\'s kunnen tot 3 meter lang worden. Ze zijn cruciaal voor de bodemgezondheid, omdat ze grond mengen en luchten, en hun uitscheidingen zijn rijk aan voedingsstoffen.',
   'Les vers de terre géants des régions tropicales peuvent atteindre jusqu\'à 3 mètres de longueur. Ils sont essentiels à la santé des sols, car ils mélangent et aèrent la terre, et leurs sécrétions sont riches en nutriments.',
   'Los gusanos de tierra gigantes de las regiones tropicales pueden alcanzar hasta 3 metros de longitud. Son cruciales para la salud del suelo, ya que mezclan y airean la tierra, y sus secreciones son ricas en nutrientes.'],
  [637, 'Hornbil', 'Neushoornvogel', 'Calao', 'Cálao',
   'Hornbilen er en markant fugl med et enormt, buet næb og en iøjnefaldende knold på det. De er kendte for en usædvanlig redeatfærd, hvor hunnen forsegles i en træhule under rugning.',
   'De neushoornvogel is een opvallende vogel met een enorme, gebogen snavel en een opvallende knop erop. Ze staan bekend om een ongewoon nestgedrag waarbij het vrouwtje wordt verzegeld in een boomholte tijdens het broeden.',
   'Le calao est un oiseau remarquable avec un énorme bec courbé et un appendice saillant. Ils sont connus pour un comportement de nidification inhabituel où la femelle est scellée dans un creux d\'arbre pendant la couvaison.',
   'El cálao es un ave notable con un enorme pico curvado y un apéndice prominente. Son conocidos por un inusual comportamiento de anidación donde la hembra es sellada en un hueco de árbol durante la incubación.'],
  [638, 'Pavian', 'Heilige baviaanfiguur', 'Mandrill (mâle)', 'Mandril (macho)',
   'Den heilige bavian er en primat med en lang, hundlignende snude. Den er en af de mest udbredte bavianarter og lever i savanner, åbne skove og endda i byer. Den lever i store sociale grupper.',
   'De heilige baviaan is een primaat met een lange, hondachtige snuit. Het is een van de meest voorkomende baviaansoorten en leeft in savannes, open bossen en zelfs in steden. Het leeft in grote sociale groepen.',
   'Le babouin sacré est un primate avec un long museau canin. C\'est l\'une des espèces de babouins les plus répandues et il vit dans les savanes, les forêts ouvertes et même dans les villes. Il vit en grands groupes sociaux.',
   'El babuino sagrado es un primate con un largo hocico canino. Es una de las especies de babuino más extendidas y vive en sabanas, bosques abiertos e incluso en ciudades. Vive en grandes grupos sociales.'],
  [639, 'Leopard (sort)', 'Zwarte panter', 'Panthère noire', 'Pantera negra',
   'Den sorte panter er ikke en separat art, men en melansitisk form af leoparden eller jaguaren. Dens mørke farve skyldes en genetisk mutation. I svagt lys kan du stadig se dens pletter.',
   'De zwarte panter is geen aparte soort, maar een melanistische vorm van de luipaard of jaguar. Zijn donkere kleur is te danken aan een genetische mutatie. In zwak licht kun je nog steeds zijn vlekken zien.',
   'La panthère noire n\'est pas une espèce distincte, mais une forme mélanistique du léopard ou du jaguar. Sa couleur sombre est due à une mutation génétique. Dans une faible lumière, on peut encore voir ses taches.',
   'La pantera negra no es una especie separada, sino una forma melanística del leopardo o el jaguar. Su color oscuro se debe a una mutación genética. En luz tenue aún puedes ver sus manchas.'],
  [640, 'Flyveagern', 'Vliegende eekhoorn', 'Écureuil volant', 'Ardilla voladora',
   'Den flyveagern flyver ikke rigtigt, men glider ved hjælp af en hudfold kaldet patagium, der strækker sig fra håndled til ankel. Den kan glide op til 150 meter fra et enkelt udgangspunkt.',
   'De vliegende eekhoorn vliegt niet echt, maar glijdt met behulp van een huidplooi genaamd patagium, die zich uitstrekt van pols tot enkel. Het kan tot 150 meter glijden vanaf een enkel startpunt.',
   'L\'écureuil volant ne vole pas vraiment, mais plane à l\'aide d\'un repli cutané appelé patagium, s\'étendant du poignet à la cheville. Il peut planer jusqu\'à 150 mètres depuis un seul point de départ.',
   'La ardilla voladora no vuela realmente, sino que planea usando un pliegue de piel llamado patagio, que se extiende desde la muñeca hasta el tobillo. Puede planear hasta 150 metros desde un solo punto de partida.'],
  [641, 'Kamgekko', 'Gekko', 'Gecko', 'Gecko',
   'Geckoen er en fascinerende firben med enestående egenskaber. Dens fødder er dækket af millioner af bittesmå hår, der giver den mulighed for at klatre på næsten enhver overflade, selv glas.',
   'De gecko is een fascinerende hagedis met unieke eigenschappen. Zijn poten zijn bedekt met miljoenen piepkleine haartjes die hem in staat stellen op bijna elk oppervlak te klimmen, zelfs glas.',
   'Le gecko est un lézard fascinant aux propriétés uniques. Ses pattes sont couvertes de millions de minuscules poils lui permettant de grimper sur presque n\'importe quelle surface, même le verre.',
   'El gecko es un lagarto fascinante con propiedades únicas. Sus patas están cubiertas de millones de pequeños pelos que le permiten trepar por casi cualquier superficie, incluso el vidrio.'],
  [642, 'Piranha', 'Piranha', 'Piranha', 'Piraña',
   'Piranhaen har et rygte for at være et af de farligste dyr i Amazonfloden. Selv om de er aggressive og har skarpe tænder, er angreb på mennesker faktisk meget sjældne under normale omstændigheder.',
   'De piranha heeft een reputatie als een van de gevaarlijkste dieren in de Amazone. Hoewel ze agressief zijn en scherpe tanden hebben, zijn aanvallen op mensen onder normale omstandigheden eigenlijk heel zeldzaam.',
   'Le piranha a la réputation d\'être l\'un des animaux les plus dangereux de l\'Amazone. Bien qu\'ils soient agressifs et aient des dents acérées, les attaques sur les humains sont en réalité très rares dans des circonstances normales.',
   'La piraña tiene reputación de ser uno de los animales más peligrosos del Amazonas. Aunque son agresivas y tienen dientes afilados, los ataques a humanos son en realidad muy raros en circunstancias normales.'],
  [643, 'Kæmpe-vandbi', 'Reuzenbijenlijster', 'Grande abeille géante', 'Abeja gigante de Wallace',
   'Wallaces kæmpe-bi er verdens største bi og kan blive op til 4 cm lang med et vingefang på 6 cm. Den blev troet at være uddød i årtier, men blev genopdaget på en ø i Indonesien i 2019.',
   'Wallace\'s reuzenbij is de grootste bij ter wereld en kan tot 4 cm lang worden met een vleugelspanwijdte van 6 cm. Men dacht dat het tientallen jaren uitgestorven was, maar werd in 2019 herontdekt op een eiland in Indonesië.',
   'L\'abeille géante de Wallace est la plus grande abeille du monde et peut atteindre jusqu\'à 4 cm de longueur avec une envergure de 6 cm. On la croyait éteinte depuis des décennies, mais elle a été redécouverte sur une île d\'Indonésie en 2019.',
   'La abeja gigante de Wallace es la abeja más grande del mundo y puede medir hasta 4 cm de longitud con una envergadura de 6 cm. Se creía extinta durante décadas, pero fue redescubierta en una isla de Indonesia en 2019.'],
  [644, 'Kæmpepyton', 'Netpython', 'Python réticulé', 'Pitón reticulada',
   'Det nettede python er verdens længste slange og kan blive over 7 meter lang. Det er en kvælerslange og lever i regnskove i Sydøstasien. Den er en dygtig svømmer og klatrer i træer.',
   'De netvormige python is de langste slang ter wereld en kan meer dan 7 meter lang worden. Het is een wurgslang en leeft in regenwouden in Zuidoost-Azië. Het is een bekwame zwemmer en klimt in bomen.',
   'Le python réticulé est le plus long serpent du monde et peut dépasser 7 mètres de longueur. C\'est un serpent constricteur qui vit dans les forêts tropicales d\'Asie du Sud-Est. C\'est un nageur habile qui grimpe aux arbres.',
   'La pitón reticulada es la serpiente más larga del mundo y puede superar los 7 metros de longitud. Es una serpiente constrictora que vive en bosques tropicales del sudeste asiático. Es nadadora hábil y trepa árboles.'],
  [645, 'Kæmpe-hundegekko', 'Tokee', 'Tokay', 'Gecko tokay',
   'Tokay-geckoen er en af de største geckoarter og er opkaldt efter dens karakteristiske "to-kay" lyd. Den er nattaktiv og lever i regnskove og huse i Sydøst-Asien. Den har et kraftigt bid.',
   'De tokay-gecko is een van de grootste geckosoorten en is vernoemd naar zijn karakteristieke "to-kay" geluid. Het is nachtactief en leeft in regenwouden en huizen in Zuidoost-Azië. Het heeft een krachtige beet.',
   'Le tokay est l\'un des plus grands geckos et est nommé d\'après son cri caractéristique "to-kay". Il est nocturne et vit dans les forêts tropicales et les maisons d\'Asie du Sud-Est. Il a une morsure puissante.',
   'El gecko tokay es una de las especies de gecko más grandes y recibe su nombre de su característico sonido "to-kay". Es nocturno y vive en bosques tropicales y casas del sudeste asiático. Tiene una mordida poderosa.'],
  // 646 skipped
  [647, 'Vandløber', 'Waterloper', 'Basilic', 'Basilisco',
   'Basilisken, også kaldet "Jesu Kristus-firben", er berømt for sin evne til at løbe på vandet. Denne utrolige færdighed opnås ved hurtigt at slå ud med dens store bagfødder på vandoverfladen.',
   'De basilisk, ook wel "Jezus Christus-hagedis" genoemd, staat bekend om zijn vermogen om op water te lopen. Deze ongelooflijke vaardigheid wordt bereikt door snel met zijn grote achterpoten op het wateroppervlak te slaan.',
   'Le basilic, également appelé "lézard de Jésus-Christ", est célèbre pour sa capacité à courir sur l\'eau. Cette incroyable habileté est atteinte en frappant rapidement ses grandes pattes arrière sur la surface de l\'eau.',
   'El basilisco, también llamado "lagarto de Jesucristo", es famoso por su capacidad de correr sobre el agua. Esta increíble habilidad se logra golpeando rápidamente sus grandes patas traseras sobre la superficie del agua.'],
  [648, 'Kæmpe-brølabe', 'Brulaap', 'Singe hurleur', 'Mono aullador',
   'Brølabeørne er de højlydeste landdyr på Jordend og kan høres over 5 km væk. Hannerne bruger disse brøl til at kommunikere territorium og til at koordinere flokbevægelse.',
   'Brulapen zijn de luidruchtigste landdieren op aarde en kunnen op meer dan 5 km afstand worden gehoord. Mannetjes gebruiken deze gebrul om territorium te communiceren en vluchtenbeweging te coördineren.',
   'Les singes hurleurs sont les animaux terrestres les plus bruyants de la Terre et peuvent être entendus à plus de 5 km de distance. Les mâles utilisent ces hurlements pour communiquer leur territoire et coordonner les mouvements de la troupe.',
   'Los monos aulladores son los animales terrestres más ruidosos de la Tierra y pueden escucharse a más de 5 km de distancia. Los machos usan estos aullidos para comunicar territorio y coordinar el movimiento de la tropa.'],
  [649, 'Spejder-abe', 'Spinaap', 'Singe araignée', 'Mono araña',
   'Spindelaberne er store New World-aber, der er kendte for deres ekstremt lange arme og præhensilehale, der bruges som en femte hånd. De er vitale frøspredere i tropiske regnskove.',
   'Spinapen zijn grote Nieuwe Wereld-apen die bekend staan om hun extreem lange armen en grijpstaart, die wordt gebruikt als een vijfde hand. Ze zijn vitale zaadverspreiders in tropische regenwouden.',
   'Les singes araignées sont de grands singes du Nouveau Monde connus pour leurs bras extrêmement longs et leur queue préhensile, utilisée comme une cinquième main. Ils sont des disperseurs de graines vitaux dans les forêts tropicales.',
   'Los monos araña son grandes monos del Nuevo Mundo conocidos por sus brazos extremadamente largos y su cola prensil, usada como una quinta mano. Son dispersores de semillas vitales en los bosques tropicales.'],
  [650, 'Kæmpe-pungdyr', 'Reuzenanteater', 'Grand fourmilier', 'Oso hormiguero gigante',
   'Den store myresluger er et unikt pattedyr uden tænder. Den har en lang, klistret tunge på op til 60 cm, der bruges til at fange myrer og termitter. Den kan spise op til 35.000 insekter om dagen.',
   'De grote miereneter is een uniek tandeloos zoogdier. Het heeft een lange, kleverige tong van maximaal 60 cm, die wordt gebruikt om mieren en termieten te vangen. Het kan tot 35.000 insecten per dag eten.',
   'Le grand fourmilier est un mammifère unique et édenté. Il a une longue langue collante allant jusqu\'à 60 cm, utilisée pour attraper fourmis et termites. Il peut manger jusqu\'à 35 000 insectes par jour.',
   'El oso hormiguero gigante es un mamífero único y sin dientes. Tiene una larga lengua pegajosa de hasta 60 cm, usada para atrapar hormigas y termitas. Puede comer hasta 35.000 insectos al día.'],
  [651, 'Kæmpe-bjørnebæver', 'Reuzenotter', 'Loutre géante', 'Nutria gigante',
   'Den kæmpe-otter er den største artful otter og kan blive op til 1,7 meter lang. Den er et socialt dyr, der lever i familiegrupper og er en dygtig jæger af fisk og krebsdyr i Sydamerikas floder.',
   'De reuzenmiereneter is de grootste miereneter en kan tot 1,7 meter lang worden. Het is een sociaal dier dat in familiegroepen leeft en een bekwame jager van vissen en schaaldieren in de rivieren van Zuid-Amerika.',
   'La loutre géante est la plus grande loutre et peut atteindre jusqu\'à 1,7 mètre de longueur. C\'est un animal social qui vit en groupes familiaux et un chasseur habile de poissons et crustacés dans les rivières d\'Amérique du Sud.',
   'La nutria gigante es la nutria más grande y puede medir hasta 1,7 metros de longitud. Es un animal social que vive en grupos familiares y un hábil cazador de peces y crustáceos en los ríos de América del Sur.'],
  [652, 'Kæmpe-tapir', 'Maleise tapir', 'Tapir de Malaisie', 'Tapir malayo',
   'Den malaysiske tapir er den største af tapirarterne og er kendetegnet ved sin markante to-farvede farve — sort foran og hvid bagpå. Den er stærkt truet på grund af habitatsødelæggelse.',
   'De Maleise tapir is de grootste van de tapirsoorten en wordt gekenmerkt door zijn opvallende tweekleurige kleur — zwart aan de voorkant en wit aan de achterkant. Het is ernstig bedreigd vanwege habitatverlies.',
   'Le tapir de Malaisie est le plus grand des tapirs et est caractérisé par sa couleur bicolore distinctive — noire à l\'avant et blanche à l\'arrière. Il est gravement menacé en raison de la destruction de l\'habitat.',
   'El tapir malayo es el más grande de las especies de tapir y se caracteriza por su distintivo color bicolor: negro en la parte delantera y blanco en la parte trasera. Está gravemente amenazado por la destrucción del hábitat.'],
  [653, 'Skovkat', 'Ocelot', 'Ocelot', 'Ocelote',
   'Ocelotten er en mellemstor plettet kat fra Amerika. Den er nattaktiv og lever i tætte regnskove og buskadser. Den er en dygtig klatrer og svømmer og jager en bred vifte af bytte.',
   'De ocelot is een middelgrote gevlekte kat uit Amerika. Het is nachtactief en leeft in dichte regenwouden en struikgewas. Het is een bekwame klimmer en zwemmer en jaagt op een breed scala aan prooidieren.',
   'L\'ocelot est un félin de taille moyenne tacheté des Amériques. Il est nocturne et vit dans les forêts tropicales denses et les broussailles. C\'est un grimpeur et nageur habile qui chasse une large gamme de proies.',
   'El ocelote es un felino mediano manchado de las Américas. Es nocturno y vive en densas selvas tropicales y matorrales. Es un hábil trepador y nadador que caza una amplia gama de presas.'],
  [654, 'Kæmpe-glubsk', 'Reuzenschildpad', 'Tortue géante des Galápagos', 'Tortuga gigante de Galápagos',
   'Galápagos-kæmpe-skildpadden er en af verdens ældste og største reptiler og kan leve over 150 år. Den er ikonisk for Darwins observationer og er et af verdens mest kendte beskyttelses-succeser.',
   'De Galapagos-reuzenschildpad is een van de oudste en grootste reptielen ter wereld en kan meer dan 150 jaar leven. Het is iconisch voor Darwins observaties en is een van de bekendste conserveringssuccessen ter wereld.',
   'La tortue géante des Galápagos est l\'un des reptiles les plus anciens et les plus grands du monde et peut vivre plus de 150 ans. Elle est emblématique des observations de Darwin et l\'un des succès de conservation les plus connus au monde.',
   'La tortuga gigante de Galápagos es uno de los reptiles más antiguos y grandes del mundo y puede vivir más de 150 años. Es icónica de las observaciones de Darwin y uno de los éxitos de conservación más conocidos del mundo.'],
  [655, 'Frø (giftig)', 'Gifkikker', 'Grenouille venimeuse', 'Rana venenosa',
   'Giftige pilefrøer er farverige frøer fra de tropiske regnskove i Mellem- og Sydamerika. Deres lyse farver advarer rovdyr om, at de er giftige. Nogle er af de mest giftige dyr på Jorden.',
   'Giftige pijlkikkers zijn kleurrijke kikkers uit de tropische regenwouden van Midden- en Zuid-Amerika. Hun heldere kleuren waarschuwen roofdieren dat ze giftig zijn. Sommige zijn de giftigste dieren op aarde.',
   'Les grenouilles venimeuses sont des grenouilles colorées des forêts tropicales d\'Amérique centrale et du Sud. Leurs couleurs vives avertissent les prédateurs qu\'elles sont toxiques. Certaines sont parmi les animaux les plus venimeux de la Terre.',
   'Las ranas venenosas son coloridas ranas de los bosques tropicales de América Central y del Sur. Sus brillantes colores advierten a los depredadores que son tóxicas. Algunas se encuentran entre los animales más venenosos de la Tierra.'],
  [656, 'Spindeldyr', 'Reuzenspin', 'Araignée géante', 'Araña gigante',
   'Kæmpe huntsman-edderkoppen er en af verdens største edderkopper med et benspand på op til 30 cm. De er nattaktive jægere og bruger hastighed og styrke frem for et spind til at fange bytte.',
   'De reuzenhuntsmansspin is een van de grootste spinnen ter wereld met een beenspanwijdte van maximaal 30 cm. Ze zijn nachtactieve jagers en gebruiken snelheid en kracht in plaats van een web om prooi te vangen.',
   'L\'araignée géante huntsman est l\'une des plus grandes araignées du monde avec une portée de pattes allant jusqu\'à 30 cm. Ce sont des chasseurs nocturnes qui utilisent la vitesse et la force plutôt qu\'une toile pour attraper des proies.',
   'La araña cazadora gigante es una de las arañas más grandes del mundo con una envergadura de hasta 30 cm. Son cazadoras nocturnas que usan velocidad y fuerza en lugar de telaraña para atrapar presas.'],
];

let id = 1341;
const langs = ['da','nl','fr','es'];

process.stdout.write(`--\n-- Daten für Tabelle \`animaltext\` (da/nl/fr/es), Biome 500+600\n--\n`);
process.stdout.write(`INSERT INTO \`animaltext\` (\`id\`, \`animalId\`, \`languageCode\`, \`animalName\`, \`animalDescription\`) VALUES\n`);

const rows = [];
for (const a of animals) {
  const [animalId, ...rest] = a;
  for (let i = 0; i < 4; i++) {
    const lang = langs[i];
    const name = rest[i];
    const desc = rest[4 + i];
    rows.push(`(${id++}, ${animalId}, '${lang}', '${q(name)}', '${q(desc)}')`);
  }
}
process.stdout.write(rows.join(',\n') + ';\n');
process.stderr.write(`Generated ${rows.length} rows, IDs 1341–${id - 1}\n`);
